import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Crimson/Seastar OSD Meeting 2019-01-15","description":"","frontmatter":{"title":"Crimson/Seastar OSD Meeting 2019-01-15","date":"2019-01-15T00:00:00.000Z","updated":"2019-01-17T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","Crimson消息传递器","OSD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Crimson_Seastar_OSD_Meeting_2019-01-15.md","filePath":"posts/2019/Crimson_Seastar_OSD_Meeting_2019-01-15.md","lastUpdated":1780460162000}'),e={name:"posts/2019/Crimson_Seastar_OSD_Meeting_2019-01-15.md"};function n(i,r,l,g,h,d){return t(),a("div",null,[...r[0]||(r[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间： <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间：&quot;">​</a></h4><p>[请填写会议时间]</p><h4 id="会议地点" tabindex="-1">会议地点： <a class="header-anchor" href="#会议地点" aria-label="Permalink to &quot;会议地点：&quot;">​</a></h4><p>[请填写会议地点]</p><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><p>[请填写参会人员名单]</p><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><p>Ceph分布式存储系统性能优化与改进</p><h4 id="会议内容" tabindex="-1">会议内容： <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容：&quot;">​</a></h4><p><strong>1. 协议与心跳机制讨论</strong></p><ul><li><strong>协议优化</strong>：会议讨论了Ceph协议的优化，特别是针对加密内容的处理。与会者认为，使用基于搜索的加密方法（Serpent）可能优于当前的方法，并建议进行性能比较。</li><li><strong>心跳机制</strong>：讨论了心跳消息的支持，认为这是确保集群健康状态的重要机制。会议探讨了心跳消息与心跳监测之间的关系，以及如何通过心跳消息保持集群的响应性。</li></ul><p><strong>2. Ceph-Rados性能分析</strong></p><ul><li><strong>性能瓶颈</strong>：与会者分析了Ceph-Rados的性能瓶颈，发现Crimson消息传递器的性能可能不如预期。会议讨论了Crimson消息传递器在用户空间和内核空间中花费的时间比例，并提出了改进建议。</li><li><strong>性能测试</strong>：会议讨论了性能测试的方法，包括使用<code>perf</code>工具进行CPU周期和I/O请求的统计。与会者建议使用多连接和更长的测试时间来获得更准确的结果。</li></ul><p><strong>3. Ceph-OSD性能优化</strong></p><ul><li><strong>单线程OSD</strong>：会议讨论了单线程OSD的性能优化，包括如何将单线程OSD映射到单个核上，以及如何避免不同协议之间的冲突。</li><li><strong>核心绑定</strong>：与会者探讨了如何通过CPU掩码将Crimson实例绑定到特定的核心上，以确保性能和稳定性。</li></ul><p><strong>4. 其他议题</strong></p><ul><li><strong>RocksDB集成</strong>：会议讨论了将RocksDB集成到Ceph中的可能性，并探讨了如何利用RocksDB的特性来提高性能。</li><li><strong>Crimson消息传递器改进</strong>：与会者讨论了Crimson消息传递器的改进，包括解决并发写入内存缓冲区的问题，以及支持多连接。</li></ul><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li><strong>性能测试</strong>：进行更全面的性能测试，包括多连接和更长的测试时间，以评估Crimson消息传递器的性能。</li><li><strong>Crimson消息传递器改进</strong>：修复Crimson消息传递器中的并发写入内存缓冲区问题，并支持多连接。</li><li><strong>单线程OSD优化</strong>：将单线程OSD映射到单个核上，并确保性能和稳定性。</li><li><strong>RocksDB集成</strong>：研究将RocksDB集成到Ceph中的可能性。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li><strong>性能测试</strong>：完成性能测试，并分析结果。</li><li><strong>Crimson消息传递器改进</strong>：提交Crimson消息传递器改进的代码，并等待合并。</li><li><strong>单线程OSD优化</strong>：完成单线程OSD优化的代码，并等待合并。</li><li><strong>RocksDB集成</strong>：研究RocksDB集成方案，并提交相关代码。</li></ul><h4 id="注意事项" tabindex="-1">注意事项： <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项：&quot;">​</a></h4><ul><li><strong>Crimson消息传递器</strong>：Crimson消息传递器的性能可能不如预期，需要进一步优化。</li><li><strong>单线程OSD</strong>：单线程OSD的性能优化需要考虑核心绑定和并发问题。</li><li><strong>RocksDB集成</strong>：RocksDB集成需要考虑性能和兼容性问题。</li></ul>',24)])])}const u=o(e,[["render",n]]);export{p as __pageData,u as default};
